insert into listings (id, group_id, added_by, title, url, raw_text, fields, created_at) values ('00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-0000000000a1', 'Baner 3BHK near Balewadi High Street', null, '3 BHK in Baner, 3rd floor, lift and covered parking. 3 bathrooms (2 attached). Semi-furnished, balcony, society gym. Rent 48,000/month.', '{"area":"Baner","rent":48000,"bhk":3,"floor":3,"lift":"yes","parking":"yes","bathrooms":3,"attached_bathrooms":2,"pet_friendly":"unknown","furnished":"semi","balcony":"yes","gym":"yes","near_metro":"no"}'::jsonb, now() - interval '6 hours');
insert into listings (id, group_id, added_by, title, url, raw_text, fields, created_at) values ('00000000-0000-4000-8000-000000000102', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-0000000000a2', 'Kothrud 3BHK, Karve Road', null, 'Spacious 3BHK Kothrud, Karve Road. 2nd floor with lift. Parking available. 3 baths, all attached. Fully furnished. Rent 42k.', '{"area":"Kothrud","rent":42000,"bhk":3,"floor":2,"lift":"yes","parking":"yes","bathrooms":3,"attached_bathrooms":3,"pet_friendly":"unknown","furnished":"full","balcony":"yes","gym":"unknown","near_metro":"yes"}'::jsonb, now() - interval '5 hours');
insert into listings (id, group_id, added_by, title, url, raw_text, fields, created_at) values ('00000000-0000-4000-8000-000000000103', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-0000000000a3', 'Aundh 3BHK, 5th floor walk-up', null, '3BHK Aundh, 5th floor, no lift (old building). Bike + car parking. 2 bathrooms. Unfurnished. Big balcony. Rent 39,000.', '{"area":"Aundh","rent":39000,"bhk":3,"floor":5,"lift":"no","parking":"yes","bathrooms":2,"attached_bathrooms":1,"pet_friendly":"unknown","furnished":"none","balcony":"yes","gym":"unknown","near_metro":"unknown"}'::jsonb, now() - interval '4 hours');
insert into listings (id, group_id, added_by, title, url, raw_text, fields, created_at) values ('00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-0000000000a1', 'Pashan 3BHK, Sus Road', null, '3BHK flat Pashan-Sus Road, 4th floor. Parking. 3 bathrooms. Semi furnished. Rent 45000.', '{"area":"Pashan","rent":45000,"bhk":3,"floor":4,"lift":"unknown","parking":"yes","bathrooms":3,"attached_bathrooms":"unknown","pet_friendly":"unknown","furnished":"semi","balcony":"unknown","gym":"unknown","near_metro":"unknown"}'::jsonb, now() - interval '3 hours');
insert into listings (id, group_id, added_by, title, url, raw_text, fields, created_at) values ('00000000-0000-4000-8000-000000000105', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-0000000000a2', 'Aundh 3BHK, ITI Road', null, 'Aundh ITI Road 3BHK, 2nd floor, lift, reserved parking. 3 bathrooms all attached, fully furnished, balcony. No gym. 15 min walk to metro? No. Rent 45,000.', '{"area":"Aundh","rent":45000,"bhk":3,"floor":2,"lift":"yes","parking":"yes","bathrooms":3,"attached_bathrooms":3,"pet_friendly":"unknown","furnished":"full","balcony":"yes","gym":"no","near_metro":"no"}'::jsonb, now() - interval '2 hours');
insert into listings (id, group_id, added_by, title, url, raw_text, fields, created_at) values ('00000000-0000-4000-8000-000000000106', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-0000000000a3', 'Balewadi 3BHK, near Baner-Pashan Link Road', null, 'Balewadi 3BHK, 7th floor, 2 lifts, covered parking, 3 bathrooms (2 attached). Semi-furnished, balcony, clubhouse gym, 5 min to metro. Pets allowed. 48k/month.', '{"area":"Balewadi","rent":48000,"bhk":3,"floor":7,"lift":"yes","parking":"yes","bathrooms":3,"attached_bathrooms":2,"pet_friendly":"yes","furnished":"semi","balcony":"yes","gym":"yes","near_metro":"yes"}'::jsonb, now() - interval '1 hours');
